-- Generated by port/make-baseline.sh: the rows of the tables the Alembic migrations seed.
SELECT line FROM (
  SELECT 'business_profile ' || x::text AS line FROM public."business_profile" x
  UNION ALL SELECT 'chart_of_accounts ' || x::text AS line FROM public."chart_of_accounts" x
  UNION ALL SELECT 'fx_rates ' || x::text AS line FROM public."fx_rates" x
) s ORDER BY line COLLATE "C";
